// colonCastRegex matches PostgreSQL `::` casts applied to positional
// placeholders like `$1::jsonb`, `$2::json[]`, or `$3::bytea`. The placeholder
// number is captured in group 1, the base type in group 2, and an optional
// array suffix (`[]`) in group 3.
//
// The alternation lists `jsonb` before `json` so that `$1::jsonb[]` matches the
// longer type first rather than leaving a stray `b`.
var colonCastRegex = regexp.MustCompile(`\$(\d+)::(jsonb|json|bytea)(\[\])?`)

// placeholderCast describes the SQL cast that a positional placeholder is bound
// to, as far as JSON adaptation cares about it.
type placeholderCast struct {
	isJSON  bool // bound to ::json or ::jsonb (possibly with an array suffix)
	isArray bool // the cast has an array suffix, e.g. ::json[]
}

// placeholderCasts scans a SQL string and returns a map from positional
// placeholder number (the N in `$N`) to the cast it's bound to. Only casts that
// are relevant to JSON text-mode adaptation are recorded; placeholders bound to
// `::bytea` are intentionally recorded as non-JSON so that []byte arguments
// bound to them are preserved.
func placeholderCasts(sql string) map[int]placeholderCast {
	casts := make(map[int]placeholderCast)
	for _, match := range colonCastRegex.FindAllStringSubmatch(sql, -1) {
		n, err := strconv.Atoi(match[1])
		if err != nil {
			continue
		}
		casts[n] = placeholderCast{
			isJSON:  match[2] == "json" || match[2] == "jsonb",
			isArray: match[3] == "[]",
		}
	}
	return casts
}

